import { Sparkline } from '@liulidesign/charts/Sparkline';

const month = [38, 41, 36, 44, 47, 43, 52, 55, 49, 58, 61, 57, 66, 70, 64, 73, 78, 71, 69, 80, 84, 79, 88, 91, 86, 95, 99, 93, 104, 108];
